mapper.update:
UPDATE chain_node
SET node_path = CONCAT(
        #{newPath},
        SUBSTRING(
            node_path,
            CHAR_LENGTH(#{oldPath}) + 1
        )
    ),
    node_level = node_level + #{levelOffset},
    parent_id = CASE
        WHEN id = #{nodeId}
        THEN #{newParentId,jdbcType=BIGINT}
        ELSE parent_id
    END,

    sort_order = CASE
        WHEN id = #{nodeId} THEN #{sortOrder}
        ELSE sort_order
    END,

    update_time = CURRENT_TIMESTAMP
WHERE chain_id = #{chainId}
  AND is_deleted = 0
  AND node_path LIKE #{oldPathPattern}
